package main
import("context";"encoding/json";"fmt";"io";"net/http";"net/http/httptest";"strings";"testing";"time")
func TestJSONAndSSETransport(t *testing.T){for _,sse:=range []bool{false,true}{t.Run(fmt.Sprint(sse),func(t *testing.T){calls,init:=0,0;srv:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){if r.Header.Get("Authorization")!="Bearer test-only"{t.Error("missing auth")};var m map[string]any;json.NewDecoder(r.Body).Decode(&m);method,_:=m["method"].(string);if method=="notifications/initialized"{w.WriteHeader(202);return};var result any;if method=="initialize"{init++;w.Header().Set("Mcp-Session-Id","session-test");result=map[string]any{"protocolVersion":"2025-06-18"}}else if method=="tools/call"{calls++;if r.Header.Get("Mcp-Session-Id")!="session-test"{t.Error("session missing")};p:=m["params"].(map[string]any);if p["name"]!=SnapshotTool{t.Error("wrong tool")};result=map[string]any{"content":[]any{map[string]any{"type":"text","text":fixture("7","wc-processing")}}}};out,_:=json.Marshal(map[string]any{"jsonrpc":"2.0","id":m["id"],"result":result});if sse{w.Header().Set("Content-Type","text/event-stream");fmt.Fprintf(w,": heartbeat\n\ndata: %s\n\n",out)}else{w.Header().Set("Content-Type","application/json");w.Write(out)}}));defer srv.Close();c:=newMCP(srv.URL,"test-only");defer c.close();for i:=0;i<2;i++{v,e:=c.call(context.Background(),SnapshotTool,map[string]any{"blog_id":1});if e!=nil{t.Fatal(e)};r,e:=parseCount(v,Config{BlogID:1},time.Now());if e!=nil||r.Count!=7{t.Fatal(r,e)}};if calls!=2||init!=1{t.Fatal(calls,init)}})}}
func TestErrorBodiesNotLeaked(t *testing.T){for _,code:=range []int{401,403,404,405,429,500}{t.Run(fmt.Sprint(code),func(t *testing.T){srv:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){w.WriteHeader(code);w.Write([]byte("SECRET_PAYLOAD"))}));defer srv.Close();c:=newMCP(srv.URL,"secret");defer c.close();_,e:=c.call(context.Background(),SnapshotTool,map[string]any{});if e==nil||strings.Contains(e.Error(),"SECRET_PAYLOAD"){t.Fatal(e)}})}}
func TestNoRedirect(t *testing.T){reached:=false;dest:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){reached=true}));defer dest.Close();src:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){http.Redirect(w,r,dest.URL,307)}));defer src.Close();c:=newMCP(src.URL,"secret");defer c.close();if _,e:=c.call(context.Background(),SnapshotTool,map[string]any{});e==nil||reached{t.Fatal("redirect followed")}}
func TestReadOnlyTools(t *testing.T){c:=newMCP("http://127.0.0.1:1","secret");defer c.close();for _,tool:=range []string{"order_update_status","nn_storeops_mu_plugin_update","other"}{if _,e:=c.call(context.Background(),tool,map[string]any{});e==nil{t.Fatal(tool)}};if _,e:=c.call(context.Background(),SnapshotTool,map[string]any{"dry_run":false});e==nil{t.Fatal("unexpected args")}}
func TestCancelNetwork(t *testing.T){entered:=make(chan struct{});release:=make(chan struct{});srv:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){io.Copy(io.Discard,r.Body);close(entered);select{case <-r.Context().Done():case <-release:}}));defer func(){close(release);srv.Close()}();c:=newMCP(srv.URL,"test");defer c.close();ctx,cancel:=context.WithCancel(context.Background());done:=make(chan error);go func(){_,e:=c.call(ctx,SnapshotTool,map[string]any{});done<-e}();<-entered;cancel();select{case e:=<-done:if e==nil{t.Fatal("no cancel")};case <-time.After(time.Second):t.Fatal("no cancellation")}}
